 "content": "def transform(grid):
    """Collapse four stacked panels using the demonstrated color precedence."""
    if not grid or len(grid) % 4:
        raise ValueError("expected four equal-height panels")
    h = len(grid) // 4
    w = len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("ragged grid")
    # Demonstrations establish 5 > 4 > 8 > 2 > background.
    priority = {5: 4, 4: 3, 8: 2, 2: 1, 0: 0}
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            out[r][c] = max((grid[k * h + r][c] for k in range(4)),
                            key=lambda value: priority.get(value, 0))
    return out

if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
